var app = new Vue({
    el: "#app",
    delimiters: ["[[", "]]"],
    data: {
      errors: [],
      newTemplateText: null,
      templates: [],
    },
    methods: {
      getData() {
        const path = window.location.origin + "/dashboard/quick-replies/data";
        axios
          .get(path)
          .then((response) => {
            this.templates = response.data;
          })
          .catch((error) => {
            console.log(error);
          });
      },
      addNewTemplate() {
        if (!this.newTemplateText) {
          this.errors.push("Không được để trống!");
        } else {
          const path = window.location.origin + "/dashboard/quick-replies";
          axios
            .post(path, {
              name: this.newTemplateText,
              u_name: this.newTemplateText.replace(/\s+/g, "").toLowerCase(),
              val: [
                {
                  stype: "text",
                  title: "",
                  payload: "",
                  image_url: ""
                },
              ],
            })
            .then((response) => {
              this.errors = [];
              this.newTemplateText = null;
              this.templates = response.data;
            })
            .catch((error) => {
              console.log(error);
            });
        }
      },
      deleteTemplate(key, id) {
          const path = window.location.origin + "/dashboard/quick-replies/" + id;
          axios
            .delete(path)
            .then((response) => {
              this.templates.splice(key, 1);
              this.$notify({
                group: "notification",
                type: response.data["status"],
                title: response.data["title"],
                text: response.data["message"],
                duration: 2500,
                speed: 1000,
              });
            })
            .catch((error) => {
              console.log(error);
            });
      },
      updateTemplate(key, id) {
        const path = window.location.origin + "/dashboard/quick-replies/" + id;
        axios
          .post(path, {
              name: this.templates[key].name,
              u_name: this.templates[key].u_name,
              val: this.templates[key].val,
          })
          .then((response) => {
            this.$notify({
              group: "notification",
              type: response.data["status"],
              title: response.data["title"],
              text: response.data["message"],
              duration: 2500,
              speed: 1000,
            });
          })
          .catch((error) => {
            console.log(error);
          });
      },
      addNewButton(key, id) {
        this.templates[key].val.push({
          stype: "text",
          title: "",
          payload: "",
          image_url: ""
        });
        this.updateTemplate(key, id);
      },
      deleteButton(key, index, id) {
        this.templates[key].val.splice(index, 1);
        this.updateTemplate(key, id);
      },
    },
    created() {
      this.getData();
    },
  });
    